240		h := Handler()
241		createPool(t, h, bucketPool)
242		createBucket(t, h, `{"id":"b1","poolId":"bp"}`)
243	
244		// Slashes, including repeated and dot segments, are part of the key.
245		mustPutObject(t, h, "b1", "a//b/../c", "x", nil)
246		rec := do(h, http.MethodGet, "/v1/buckets/b1/objects/a//b/../c", "")
