251	func TestAuditEventsPagination(t *testing.T) {
252		h := Handler()
253		auditFixture(t, h)
254		want := expectedAuditFixture()
255	
256		// Pages of 5 walk the whole log; hasMore is true until the final page.
257		v := getAuditEvents(t, h, "/v1/audit-events?limit=5")
258		page := v["items"].([]any)
259		if len(page) != 5 || !v["hasMore"].(bool) || v["nextAfter"].(float64) != 5 {
260			t.Fatalf("page 1 = %v", v)
261		}
262		for i := 0; i < 5; i++ {
263			checkEvent(t, page[i], want[i])
264		}
265	
266		v = getAuditEvents(t, h, "/v1/audit-events?after=5&limit=5")
267		page = v["items"].([]any)
268		if len(page) != 5 || !v["hasMore"].(bool) || v["nextAfter"].(float64) != 10 {
269			t.Fatalf("page 2 = %v", v)
270		}
271		for i := 0; i < 5; i++ {
272			checkEvent(t, page[i], want[5+i])
273		}
274	
275		// Final partial page: 5 items, hasMore false, nextAfter = last sequence.
276		v = getAuditEvents(t, h, "/v1/audit-events?after=15&limit=5")
277		page = v["items"].([]any)
278		if len(page) != 5 || v["hasMore"].(bool) || v["nextAfter"].(float64) != 20 {
279			t.Fatalf("final page = %v", v)
280		}
281		for i := 0; i < 5; i++ {
282			checkEvent(t, page[i], want[15+i])
283		}
284	
285		// after at the last sequence returns an empty page echoing after.
286		v = getAuditEvents(t, h, "/v1/audit-events?after=20")
287		items := v["items"].([]any)
288		if len(items) != 0 || v["hasMore"].(bool) || v["nextAfter"].(float64) != 20 {
289			t.Fatalf("tail page = %v", v)
290		}
291	
292		// after beyond the maximum sequence: empty page, nextAfter echoes after.
293		v = getAuditEvents(t, h, "/v1/audit-events?after=9999")
294		items = v["items"].([]any)
295		if len(items) != 0 || v["hasMore"].(bool) || v["nextAfter"].(float64) != 9999 {
296			t.Fatalf("beyond-max page = %v", v)
297		}
298	}
