	mustPutObject(t, h, "b1", "k", "aaa", nil)
	if rec := do(h, http.MethodDelete, "/v1/buckets/b1/objects/k", ""); rec.Code != http.StatusNoContent {
		t.Fatalf("first delete = %d", rec.Code)
	}
